(window.EXSUB_C=window.EXSUB_C||{})[14]={"a-1":[{"t":"Defensor del Pueblo: cuadro resumen del temario","h":"<div class=\"vis\"><div class=\"vis-t\"><i>▦</i>Defensor del Pueblo: cuadro resumen del temario</div><div class=\"vis-tabla\"><div class=\"vt-cab\"><span>Apartado</span><span>Contenido</span></div><div class=\"vt-nodo\"><div class=\"vt-et \">CONCEPTO</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\"><mark class=\"m-destacable\">Alto comisionado</mark> de las <mark class=\"m-resp\">Cortes Generales</mark> designado por éstas para la defensa de los derechos contenidos en el <mark class=\"m-destacable\">Título I</mark> a cuyo efecto <mark class=\"m-accion\">podrá</mark> <mark class=\"m-destacable\">supervisar la actividad de la Administración</mark> dando cuenta a las Cortes</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et \">MANDATO</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Elegido por las Cortes Generales por un periodo de <mark class=\"m-resp\">cinco años</mark></div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et \">ELECCIÓN Y NOMBRAMIENTO</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Una vez propuesto, el candidato o candidatos al Pleno de las Cámaras por acuerdo de <mark class=\"m-plazo\">mayoría simple</mark> de la <mark class=\"m-autoridad\">Comisión</mark> <mark class=\"m-destacable\">Mixta Congreso-Senado</mark></div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\"><mark class=\"m-accion\">Se convocará</mark> en término <u class=\"m-clave\">no inferior</u> a <mark class=\"m-resp\">diez días</mark> al <mark class=\"m-destacable\">Pleno del Congreso</mark> para que proceda a la votación y <mark class=\"m-accion\">será designado</mark> el que obtenga <mark class=\"m-plazo\">mayoría de 3/5</mark> de los miembros del Congreso y, posteriormente, en el plazo máximo de <mark class=\"m-resp\">20 días</mark>, fuese ratificado por <mark class=\"m-plazo\">3/5 del Senado</mark></div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Si no se logra: sucesivas propuestas de la <mark class=\"m-autoridad\">Comisión</mark> durante <mark class=\"m-plazo\">un mes</mark>, para lo cual <mark class=\"m-accion\">hará</mark> falta <mark class=\"m-plazo\">3/5 del Congreso</mark> y <mark class=\"m-plazo\">mayoría absoluta del Senado</mark></div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et \">CESE</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Por renuncia</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Por expiración del plazo de su nombramiento</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Por muerte o por incapacidad sobrevenida</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Por actuar con <mark class=\"m-destacable\">notoria negligencia</mark> en el cumplimiento de las obligaciones y deberes del cargo</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Por haber sido condenado, mediante <mark class=\"m-destacable\">sentencia firme</mark>, por <mark class=\"m-destacable\">delito doloso</mark></div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et \">PRERROGATIVAS</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\"><u class=\"m-clave\">No</u> está sujeto a <mark class=\"m-destacable\">mandato imperativo</mark></div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\"><mark class=\"m-destacable\">Inviolabilidad</mark> por las opiniones que formule o los actos que realice en el ejercicio de sus funciones</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Solo <mark class=\"m-accion\">podrá ser detenido</mark> <mark class=\"m-destacable\">en caso de flagrante delito</mark> mientras permanezca en el ejercicio de sus funciones (su inculpación, prisión, procesamiento y juicio corresponde <u class=\"m-clave\">exclusivamente</u> a la <mark class=\"m-resp\">Sala de lo Penal del Tribunal Supremo</mark>)</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et \">CARACTERÍSTICAS</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Actuaciones iniciadas de <mark class=\"m-destacable\">oficio</mark> o a <mark class=\"m-destacable\">instancia de parte</mark></div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\"><mark class=\"m-destacable\">Actuación gratuita</mark> (no siendo necesario ni <mark class=\"m-autoridad\">abogado</mark> ni procurador)</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Es una de las <mark class=\"m-destacable\">instituciones de garantía</mark> que integra el sistema de protección de derechos</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et \">INCOMPATIBILIDADES</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Mandato representativo</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Cargo político o <mark class=\"m-destacable\">propaganda política</mark></div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Servicio activo en la Administración Pública</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\"><mark class=\"m-destacable\">Afiliación</mark> a partido político, sindicación y dirección del partido político, asociación y fundación</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Carrera judicial y <mark class=\"m-autoridad\">fiscal</mark></div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Actividad laboral, profesional, liberal y mercantil</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et \">FUNCIONES PRINCIPALES</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\"><mark class=\"m-destacable\">Protección</mark> de derechos y deberes fundamentales</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\"><mark class=\"m-destacable\">Supervisión</mark>, de oficio o a instancia de parte, de todas las administraciones públicas</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et \">ADJUNTOS</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\"><mark class=\"m-plazo\">2 adjuntos</mark> (propuestos por el <mark class=\"m-autoridad\">Defensor</mark> del Pueblo)</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\"><mark class=\"m-destacable\">Auxilio</mark> al <mark class=\"m-autoridad\">Defensor</mark> del Pueblo</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et \">INFORMES</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\"><mark class=\"m-destacable\">Anual</mark>: ante las Cortes Generales cuando se hallen reunidas en periodo ordinario de sesiones</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\"><mark class=\"m-destacable\">Extraordinario</mark>: dirigido a las <mark class=\"m-resp\">Diputaciones Permanentes</mark> si las Cortes no se encontraran reunidas, cuando la gravedad o urgencia de los hechos lo aconsejen</div></div></div></div></div></div>"}],"a-2":[{"t":"Elección del Defensor del Pueblo (art. 2)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Elección del Defensor del Pueblo (art. 2)</div><div class=\"vis-flujo\"><div class=\"vis-paso \"><span class=\"et\">1</span>La <mark class=\"m-autoridad\">Comisión</mark> <mark class=\"m-destacable\">Mixta Congreso-Senado</mark> se reúne cuando lo acuerden conjuntamente los Presidentes del Congreso y del Senado y, en todo caso, para proponer al candidato o candidatos. Sus acuerdos: <mark class=\"m-plazo\">mayoría simple</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">2</span>Propuesto el candidato, se convoca al <mark class=\"m-destacable\">Pleno del Congreso</mark> en término <u class=\"m-clave\">no inferior</u> a <mark class=\"m-resp\">diez días</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">3</span>Es designado quien obtenga <mark class=\"m-plazo\">3/5 de los miembros del Congreso</mark> y, en un plazo máximo de <mark class=\"m-resp\">veinte días</mark>, sea ratificado por la <mark class=\"m-plazo\">misma mayoría del Senado</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-bifurca\"><div class=\"vis-paso si\"><span class=\"et\">Si se logra</span>Nombramiento acreditado por la firma conjunta de los Presidentes del Congreso y del Senado y publicado en el BOE; juramento o promesa ante las Mesas de ambas Cámaras (art. 4)</div><div class=\"vis-paso no\"><span class=\"et\">Si no se logra</span>Nueva sesión de la <mark class=\"m-autoridad\">Comisión</mark> y, en el plazo máximo de <mark class=\"m-plazo\">un mes</mark>, nuevas propuestas: basta <mark class=\"m-plazo\">3/5 en el Congreso</mark> y <mark class=\"m-plazo\">mayoría absoluta del Senado</mark></div></div></div></div>"}],"a-5":[{"t":"Cese y vacante del Defensor del Pueblo (art. 5)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Cese y vacante del Defensor del Pueblo (art. 5)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">Cese</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">Causas de cese:<div class=\"vis-sub\"><span>renuncia</span><span>expiración del plazo de su nombramiento</span><span>muerte o incapacidad sobrevenida</span><span><mark class=\"m-destacable\">notoria negligencia</mark> en el cumplimiento de los deberes del cargo</span><span><mark class=\"m-destacable\">sentencia firme</mark> por <mark class=\"m-destacable\">delito doloso</mark></span></div></div><div class=\"vis-rama\">La vacante se declara:<div class=\"vis-sub\"><span>por el <mark class=\"m-resp\">Presidente del Congreso</mark>: muerte, renuncia y expiración del plazo</span><span>en los demás casos: mayoría de <mark class=\"m-resp\">3/5 de los componentes de cada Cámara</mark>, mediante debate y previa <mark class=\"m-autoridad\">audiencia</mark> del interesado</span></div></div><div class=\"vis-rama\">Nuevo nombramiento: procedimiento en plazo <u class=\"m-clave\">no superior</u> a <mark class=\"m-plazo\">un mes</mark></div><div class=\"vis-rama\">Mientras tanto, desempeñan sus funciones interinamente, en su propio orden, los <mark class=\"m-resp\">Adjuntos</mark></div></div></div></div>"}],"a-18":[{"t":"Tramitación de las quejas (arts. 15 a 18)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Tramitación de las quejas (arts. 15 a 18)</div><div class=\"vis-flujo\"><div class=\"vis-paso \"><span class=\"et\">15</span>Queja firmada por el interesado (nombre, apellidos y domicilio), escrito razonado en papel común, <mark class=\"m-resp\">plazo máximo de un año</mark> desde que tuvo conocimiento de los hechos. Actuaciones <mark class=\"m-destacable\">gratuitas</mark>: sin Letrado ni Procurador. De toda queja se <mark class=\"m-destacable\">acusa recibo</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">17</span>El <mark class=\"m-autoridad\">Defensor</mark> <mark class=\"m-destacable\">registra, acusa recibo, tramita o rechaza</mark>. Rechazo en <mark class=\"m-destacable\">escrito motivado</mark> (puede informar de las vías oportunas). <u class=\"m-clave\">Anónimas</u>: se rechazan; mala fe, carencia de fundamento, inexistencia de pretensión o perjuicio a tercero: puede rechazarlas. Decisiones <u class=\"m-clave\">no susceptibles de recurso</u></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">17.2</span>Si hay <mark class=\"m-destacable\">resolución judicial pendiente</mark>: no examen individual (se suspende si luego hay demanda o recurso), pero sí investigación de los problemas generales</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">18</span>Admitida: investigación <mark class=\"m-resp\">sumaria e informal</mark>; se da cuenta al organismo para que su Jefe remita informe escrito en el plazo máximo de <mark class=\"m-resp\">quince días</mark> (ampliable)</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">18.2</span>La negativa o negligencia en el envío del informe puede ser considerada <mark class=\"m-destacable\">hostil y entorpecedora</mark>: se hace pública de inmediato y se destaca en el informe anual o especial</div></div></div>"}],"a-37":[{"t":"Defensor del Pueblo: concepto, elección, cese, competencias y procedimiento (cuadro del temario)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>▦</i>Defensor del Pueblo: concepto, elección, cese, competencias y procedimiento (cuadro del temario)</div><div class=\"vis-tabla\"><div class=\"vt-cab\"><span>Apartado</span><span>Contenido</span></div><div class=\"vt-nodo\"><div class=\"vt-et \">CONCEPTO</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">(<mark class=\"m-destacable\">art. 54 CE</mark>) El <mark class=\"m-autoridad\">Defensor</mark> del Pueblo es el <mark class=\"m-destacable\">alto comisionado de las Cortes Generales</mark> designado por éstas para la defensa de los derechos comprendidos en el <mark class=\"m-destacable\">Título I</mark> de la Constitución, a cuyo efecto <mark class=\"m-accion\">podrá supervisar</mark> la actividad de la Administración, dando cuenta a las Cortes Generales. <mark class=\"m-accion\">Ejercerá</mark> las funciones que le encomienda la Constitución y la presente Ley</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et \">CARACTERÍSTICAS</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Depende <mark class=\"m-destacable\">única y exclusivamente</mark> de las Cortes Generales</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Tiene como misión la <mark class=\"m-destacable\">vigilancia y la defensa del Título I</mark> de la Constitución</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Supervisa la actividad de la Administración</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et \">ELECCIÓN</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\"><mark class=\"m-accion\">Será elegido</mark> por las Cortes Generales por un periodo de <mark class=\"m-resp\">5 años</mark></div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Lo designan las Cortes → <mark class=\"m-autoridad\">Comisión</mark> <mark class=\"m-destacable\">Mixta Congreso-Senado</mark> → por <mark class=\"m-plazo\">mayoría simple</mark> → proposición del candidato <u class=\"m-clave\">no inferior</u> a <mark class=\"m-resp\">10 días</mark> al <mark class=\"m-destacable\">Pleno del Congreso</mark></div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Votación favorable de las <mark class=\"m-plazo\">3/5 partes</mark> del Congreso y, posteriormente (plazo de <mark class=\"m-resp\">20 días</mark>), la misma mayoría de votos del Senado</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Cualquier <mark class=\"m-destacable\">español mayor de edad</mark> en pleno disfrute de sus derechos <mark class=\"m-destacable\">civiles y políticos</mark></div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Nombramiento por la firma conjunta de los Presidentes del Congreso y del Senado; <mark class=\"m-accion\">se publicará</mark> en el BOE</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Juramento o promesa ante las <mark class=\"m-resp\">Mesas de ambas Cámaras</mark></div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Puede delegar funciones en un <mark class=\"m-destacable\">Adjunto Primero</mark> y un <mark class=\"m-destacable\">Adjunto Segundo</mark></div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et \">PRERROGATIVAS</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\"><mark class=\"m-accion\">Gozará</mark> de <mark class=\"m-destacable\">inviolabilidad</mark></div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">En caso de <mark class=\"m-destacable\">flagrante delito</mark> → inculpación, prisión, procesamiento y juicio: <mark class=\"m-resp\">Sala de lo Penal del Tribunal Supremo</mark></div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Aplicable también a los Adjuntos</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et \">INCOMPATIBILIDADES</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Incompatible con todo <mark class=\"m-destacable\">mandato representativo</mark></div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Debe cesar dentro de los <mark class=\"m-resp\">10 días siguientes</mark> a su nombramiento y antes de tomar posesión en toda situación de incompatibilidad; si fuese sobrevenida en el cargo, se entiende <mark class=\"m-destacable\">renuncia</mark></div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et \">CAUSAS DE CESE</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Por renuncia · por expiración del plazo de su nombramiento · por muerte o por incapacidad sobrevenida</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Por actuar con <mark class=\"m-destacable\">notoria negligencia</mark> en el cumplimiento de las obligaciones y deberes del cargo · por haber sido condenado, mediante <mark class=\"m-destacable\">sentencia firme</mark>, por <mark class=\"m-destacable\">delito doloso</mark></div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\"><mark class=\"m-accion\">Se declarará</mark> por el <mark class=\"m-resp\">Presidente del Congreso</mark> en los casos de muerte, renuncia y expiración del plazo del mandato; en los demás casos, por mayoría de <mark class=\"m-resp\">3/5</mark> de los componentes de cada Cámara, mediante debate y previa <mark class=\"m-autoridad\">audiencia</mark> del interesado</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Vacante el cargo <mark class=\"m-accion\">se iniciará</mark> el procedimiento para el nombramiento de nuevo <mark class=\"m-autoridad\">Defensor</mark> en plazo <u class=\"m-clave\">no superior</u> a <mark class=\"m-plazo\">un mes</mark></div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">En los casos de muerte, cese o incapacidad temporal o definitiva y mientras las Cortes no designen a otro, <mark class=\"m-accion\">desempeñarán</mark> sus funciones, interinamente y en su propio orden, los <mark class=\"m-destacable\">Adjuntos</mark></div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et \">COMPETENCIAS</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">De <mark class=\"m-destacable\">oficio</mark> o a <mark class=\"m-destacable\">instancia de parte</mark></div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Quejas sobre el funcionamiento de la <mark class=\"m-destacable\">Administración de Justicia</mark>: las dirige al <mark class=\"m-autoridad\">Ministerio Fiscal</mark> para que investigue y adopte las medidas oportunas, o da traslado al <mark class=\"m-autoridad\">Consejo</mark> <mark class=\"m-destacable\">General del Poder Judicial</mark> según el tipo de reclamación, sin perjuicio de la referencia en su informe general a las Cortes</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et \">PROCEDIMIENTO</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Queja → cualquier <mark class=\"m-autoridad\">persona</mark> → presentación por escrito → plazo de <mark class=\"m-resp\">1 año</mark></div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Investigación de la actuación administrativa → <mark class=\"m-resp\">15 días</mark> para que emita informe, plazo ampliable</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Efectos: <mark class=\"m-accion\">podrá interponer</mark> los recursos de <mark class=\"m-destacable\">inconstitucionalidad y de amparo</mark> y formular advertencia, recomendación o sugerencia al funcionario responsable</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Informe a las Cortes Generales de la gestión realizada; en caso de gravedad o urgencia, <mark class=\"m-destacable\">informe extraordinario</mark> a las <mark class=\"m-resp\">Diputaciones Permanentes</mark>. Ambos informes <mark class=\"m-accion\">serán publicados</mark></div></div></div></div></div></div>"},{"t":"RECUERDA del temario (R1 a R9): Ley Orgánica del Defensor del Pueblo","h":"<div class=\"vis\"><div class=\"vis-t\"><i>▦</i>RECUERDA del temario (R1 a R9): Ley Orgánica del Defensor del Pueblo</div><div class=\"vis-tabla\"><div class=\"vt-cab\"><span>Ficha</span><span>Pregunta → respuesta</span></div><div class=\"vt-nodo\"><div class=\"vt-et \">LO del <mark class=\"m-autoridad\">Defensor</mark> del Pueblo</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">R1</span><div class=\"vt-t\">El <mark class=\"m-autoridad\">Defensor</mark> del Pueblo es el alto comisionado de las Cortes Generales designado por éstas para la defensa de los derechos comprendidos en el: → <mark class=\"m-resp\">Título I de la Constitución</mark>, a cuyo efecto <mark class=\"m-accion\">podrá supervisar</mark> la actividad de la Administración, dando cuenta a las Cortes Generales</div></div><div class=\"vt-hoja\"><span class=\"vt-p o\">R2</span><div class=\"vt-t\">El <mark class=\"m-autoridad\">Defensor</mark> del Pueblo <mark class=\"m-accion\">será elegido</mark> por: → las <mark class=\"m-resp\">Cortes Generales</mark> para un periodo de <mark class=\"m-resp\">cinco años</mark>, y <mark class=\"m-accion\">se dirigirá</mark> a las mismas a través de los Presidentes del Congreso y del Senado, respectivamente</div></div><div class=\"vt-hoja\"><span class=\"vt-p o\">R3</span><div class=\"vt-t\"><mark class=\"m-accion\">Podrá ser elegido</mark> <mark class=\"m-autoridad\">Defensor</mark> del Pueblo cualquier español mayor de edad que se encuentre en el pleno disfrute de sus derechos: → <mark class=\"m-resp\">civiles y políticos</mark></div></div><div class=\"vt-hoja\"><span class=\"vt-p o\">R4</span><div class=\"vt-t\">El <mark class=\"m-autoridad\">Defensor</mark> del Pueblo <mark class=\"m-accion\">deberá cesar</mark> en toda situación de incompatibilidad que pudiere afectarle, entendiéndose en caso contrario que no acepta el nombramiento: → <mark class=\"m-resp\">dentro de los diez días siguientes a su nombramiento y antes de tomar posesión</mark></div></div><div class=\"vt-hoja\"><span class=\"vt-p o\">R5</span><div class=\"vt-t\">La actividad del <mark class=\"m-autoridad\">Defensor</mark> del Pueblo <mark class=\"m-accion\">no se verá</mark> interrumpida en los casos en que las Cortes Generales: → <mark class=\"m-resp\">no se encuentren reunidas, hubieren sido disueltas o hubiere expirado su mandato</mark></div></div><div class=\"vt-hoja\"><span class=\"vt-p o\">R6</span><div class=\"vt-t\">Toda queja <mark class=\"m-accion\">se presentará</mark> firmada por el interesado, con indicación de su nombre, apellidos y domicilio, en escrito razonado en papel común y en el plazo máximo de: → <mark class=\"m-resp\">un año</mark>, contado a partir del momento en que tuviera conocimiento de los hechos objeto de la misma</div></div><div class=\"vt-hoja\"><span class=\"vt-p o\">R7</span><div class=\"vt-t\">Todos los poderes públicos están obligados a auxiliar al <mark class=\"m-autoridad\">Defensor</mark> del Pueblo en sus investigaciones e inspecciones: → <mark class=\"m-resp\">con carácter preferente y urgente</mark></div></div><div class=\"vt-hoja\"><span class=\"vt-p o\">R8</span><div class=\"vt-t\">Cuando las actuaciones practicadas revelen que la queja ha sido originada presumiblemente por el abuso, arbitrariedad, discriminación, error, negligencia u omisión de un funcionario, el <mark class=\"m-autoridad\">Defensor</mark> del Pueblo <mark class=\"m-accion\">podrá:</mark> → <mark class=\"m-resp\">dirigirse al afectado haciéndole constar su criterio al respecto</mark></div></div><div class=\"vt-hoja\"><span class=\"vt-p o\">R9</span><div class=\"vt-t\">El <mark class=\"m-autoridad\">Defensor</mark> del Pueblo está legitimado para interponer los recursos de inconstitucionalidad y de amparo, de acuerdo con lo dispuesto en: → <mark class=\"m-resp\">la Constitución y en la Ley Orgánica del Tribunal Constitucional</mark></div></div></div></div></div></div>"},{"t":"Plazos de la LO 3/1981 (resumen)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⏱</i>Plazos de la LO 3/1981 (resumen)</div><div class=\"vis-plazos\"><div class=\"vis-plazo\"><span class=\"n\">5 años</span>Mandato del <mark class=\"m-autoridad\">Defensor</mark> del Pueblo (art. 2.1) · <mark class=\"m-resp\">a los cinco años de entrada en vigor</mark> puede proponer modificaciones de la Ley (disposición transitoria)</div><div class=\"vis-plazo\"><span class=\"n\">≥ 10 días</span>Convocatoria del Pleno del Congreso tras la propuesta (art. 2.4) · plazo para responder el afectado: <u class=\"m-clave\">nunca inferior</u> a diez días, prorrogable por la mitad (art. 20.2)</div><div class=\"vis-plazo\"><span class=\"n\">20 días</span>Plazo máximo para la ratificación por 3/5 del Senado (art. 2.4)</div><div class=\"vis-plazo\"><span class=\"n\">1 mes</span>Nuevas propuestas si no se alcanzan las mayorías (art. 2.5) · inicio del procedimiento tras la vacante, <u class=\"m-clave\">no superior</u> a un mes (art. 5.3) · respuesta escrita a las recomendaciones, <u class=\"m-clave\">no superior</u> a un mes (art. 30.1)</div><div class=\"vis-plazo\"><span class=\"n\">10 días</span>Cesar en la incompatibilidad desde el nombramiento y antes de tomar posesión (art. 7.2)</div><div class=\"vis-plazo\"><span class=\"n\">1 año</span>Plazo máximo para presentar la queja desde que se tuvo conocimiento de los hechos (art. 15.1)</div><div class=\"vis-plazo\"><span class=\"n\">15 días</span>Informe escrito del organismo al que se da cuenta de la queja, ampliable (art. 18.1)</div></div></div>"}],"b-7":[{"t":"Órganos de la Institución según el Reglamento","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Órganos de la Institución según el Reglamento</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-autoridad\">Defensor</mark> <mark class=\"m-destacable\">del Pueblo</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">Adjuntos (Primero y Segundo)<div class=\"vis-sub\"><span><mark class=\"m-resp\">Adjunto Primero</mark>: coordina los servicios y el despacho ordinario con el <mark class=\"m-autoridad\">Secretario</mark> General</span><span>El Adjunto <mark class=\"m-autoridad\">delegado</mark> preside el <mark class=\"m-autoridad\">Consejo</mark> Asesor del MNP</span></div></div><div class=\"vis-rama\"><mark class=\"m-resp\">Junta de Coordinación y Régimen Interior</mark>: <mark class=\"m-autoridad\">Defensor,</mark> Adjuntos y <mark class=\"m-autoridad\">Secretario</mark> general (voz y sin voto)</div><div class=\"vis-rama\"><mark class=\"m-resp\">Consejo Asesor</mark> del Mecanismo Nacional de Prevención de la Tortura<div class=\"vis-sub\"><span>Adjuntos (natos) + máximo 10 Vocales</span><span>Preside el Adjunto <mark class=\"m-autoridad\">delegado</mark></span></div></div><div class=\"vis-rama\"><mark class=\"m-autoridad\">Secretario</mark> General<div class=\"vis-sub\"><span>Servicio de Régimen Económico (3 Secciones)</span><span>Servicio de Régimen Interior, Estudios, Documentación y Publicaciones: Registro General y <mark class=\"m-autoridad\">Oficina</mark> de Información</span><span>Sección de Archivo: bajo su directa responsabilidad</span></div></div><div class=\"vis-rama\"><mark class=\"m-destacable\">Gabinete Técnico</mark> (dirigido por uno de los Asesores): <mark class=\"m-autoridad\">Secretaría</mark> particular, estudios e informes, protocolo · Gabinete de Prensa e Información</div></div></div></div>"}],"b-22":[{"t":"Consejo Asesor del Mecanismo Nacional de Prevención de la Tortura (cuadro del temario)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>▦</i>Consejo Asesor del Mecanismo Nacional de Prevención de la Tortura (cuadro del temario)</div><div class=\"vis-tabla\"><div class=\"vt-cab\"><span>Apartado</span><span>Contenido</span></div><div class=\"vt-nodo\"><div class=\"vt-et \">NATURALEZA</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\"><mark class=\"m-autoridad\">Órgano</mark> <mark class=\"m-destacable\">de cooperación técnica y jurídica</mark> del Mecanismo Nacional de Prevención</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et \">FORMACIÓN</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\">Integrado por los <mark class=\"m-destacable\">Adjuntos</mark> del <mark class=\"m-autoridad\">Defensor</mark> del Pueblo (miembros natos) y un <mark class=\"m-resp\">máximo de 10 Vocales</mark> (mayores de edad, en pleno disfrute de sus derechos civiles y políticos, con reconocida trayectoria en defensa de los Derechos Humanos)</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et \"><mark class=\"m-autoridad\">PRESIDENCIA</mark></div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\"><mark class=\"m-destacable\">Adjunto</mark> en quien delegue el <mark class=\"m-autoridad\">Defensor</mark> del Pueblo las funciones del mecanismo; en caso de ausencia o vacante lo sustituye el otro Adjunto</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et v\">DESIGNACIÓN DE LOS VOCALES</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\"><mark class=\"m-plazo\">1</mark> <mark class=\"m-autoridad\">Consejo</mark> General de la Abogacía <mark class=\"m-autoridad\">(Abogado)</mark></div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\"><mark class=\"m-plazo\">1</mark> Organización Médica Colegial (Médico)</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\"><mark class=\"m-plazo\">1</mark> <mark class=\"m-autoridad\">Consejo</mark> General de Colegios Oficiales de Psicólogos de España (Psicólogo)</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\"><mark class=\"m-resp\">Hasta 2</mark> a propuesta conjunta de los organismos con convenios de colaboración con el <mark class=\"m-autoridad\">Defensor</mark> para las funciones del MNP, si así está previsto (<u class=\"m-clave\">no más de un representante por entidad</u>)</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\"><mark class=\"m-plazo\">5</mark> elegidos de entre las candidaturas, a título personal o en representación de organizaciones de la sociedad civil, presentadas al <mark class=\"m-autoridad\">Defensor</mark> del Pueblo</div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Designados por el <mark class=\"m-autoridad\">Defensor</mark> del Pueblo por <mark class=\"m-resp\">4 años</mark> y renovados por <mark class=\"m-resp\">mitades cada 2</mark>; también pone fin a sus funciones · <mark class=\"m-destacable\">Convocatoria pública</mark> (candidaturas en 15 días naturales) · <u class=\"m-clave\">No</u> perciben retribuciones, salvo indemnizaciones por razón del servicio</div></div></div></div><div class=\"vt-nodo\"><div class=\"vt-et \">REUNIONES</div><div class=\"vt-hijos\"><div class=\"vt-hoja sp\"><div class=\"vt-t\"><mark class=\"m-resp\">Al menos dos veces al año</mark></div></div><div class=\"vt-hoja sp\"><div class=\"vt-t\">Pueden asistir miembros del personal del <mark class=\"m-autoridad\">Defensor,</mark> representantes de organismos internacionales de Derechos Humanos u otras <mark class=\"m-autoridad\">personas</mark> convocadas por indicación del <mark class=\"m-autoridad\">Presidente</mark></div></div></div></div></div></div>"}],"b-38":[{"t":"Faltas disciplinarias del personal (arts. 36 a 38)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>Faltas disciplinarias del personal (arts. 36 a 38)</div><div class=\"vis-comp\" style=\"--n:3\"><div class=\"vis-col\"><h5>Falta LEVE</h5><ul><li>Prescribe a los <mark class=\"m-resp\">dos meses</mark></li><li>Sanción: <mark class=\"m-resp\">apercibimiento</mark> o suspensión de empleo y remuneración de <mark class=\"m-resp\">uno a diez días</mark></li><li>La impone el <mark class=\"m-destacable\">superior jerárquico</mark>; <u class=\"m-clave\">no</u> hay expediente, pero se oye al presunto infractor</li></ul></div><div class=\"vis-col\"><h5>Falta GRAVE</h5><ul><li>Prescribe a los <mark class=\"m-resp\">seis meses</mark></li><li>Sanción: suspensión de empleo y remuneración de <mark class=\"m-resp\">hasta seis meses</mark></li><li>Expediente: pliego de cargos, prueba y propuesta de resolución; incoación e imposición por el <mark class=\"m-autoridad\">Secretario</mark> <mark class=\"m-destacable\">general</mark> (suspensión y separación: solo el <mark class=\"m-autoridad\">Defensor)</mark></li></ul></div><div class=\"vis-col\"><h5>Falta MUY GRAVE</h5><ul><li>Prescribe al <mark class=\"m-resp\">año</mark></li><li>Sanción: suspensión de empleo y remuneración o separación del servicio de <mark class=\"m-resp\">seis meses a seis años</mark></li><li>Mismo expediente que la grave; las sanciones de <mark class=\"m-destacable\">suspensión y separación</mark> solo las impone el <mark class=\"m-autoridad\">Defensor</mark> <mark class=\"m-destacable\">del Pueblo</mark></li></ul></div></div></div>"}],"b-41":[{"t":"RECUERDA del temario (R10 a R15): Reglamento del Defensor del Pueblo","h":"<div class=\"vis\"><div class=\"vis-t\"><i>▦</i>RECUERDA del temario (R10 a R15): Reglamento del Defensor del Pueblo</div><div class=\"vis-tabla\"><div class=\"vt-cab\"><span>Ficha</span><span>Pregunta → respuesta</span></div><div class=\"vt-nodo\"><div class=\"vt-et \">Reglamento del <mark class=\"m-autoridad\">Defensor</mark> del Pueblo</div><div class=\"vt-hijos\"><div class=\"vt-hoja\"><span class=\"vt-p o\">R10</span><div class=\"vt-t\">Para el ejercicio de sus funciones, el <mark class=\"m-autoridad\">Defensor</mark> del Pueblo <mark class=\"m-accion\">estará asistido</mark> por: → <mark class=\"m-resp\">una Junta de Coordinación y Régimen Interior</mark></div></div><div class=\"vt-hoja\"><span class=\"vt-p o\">R11</span><div class=\"vt-t\">El Adjunto en el que el <mark class=\"m-autoridad\">Defensor</mark> del Pueblo delegue las funciones del Mecanismo Nacional de Prevención <mark class=\"m-accion\">asumirá</mark> la <mark class=\"m-autoridad\">presidencia</mark> de: → <mark class=\"m-resp\">su Consejo asesor</mark></div></div><div class=\"vt-hoja\"><span class=\"vt-p o\">R12</span><div class=\"vt-t\">El <mark class=\"m-autoridad\">Consejo</mark> Asesor <mark class=\"m-accion\">estará integrado</mark> por: → <mark class=\"m-resp\">los Adjuntos del Defensor del Pueblo, como miembros natos, además de por un máximo de 10 Vocales</mark></div></div><div class=\"vt-hoja\"><span class=\"vt-p o\">R13</span><div class=\"vt-t\">Dependiendo del Servicio de Régimen Interior, Estudio, Documentación y Publicaciones, <mark class=\"m-accion\">existirá:</mark> → <mark class=\"m-resp\">un Registro General y una Oficina de Información</mark></div></div><div class=\"vt-hoja\"><span class=\"vt-p o\">R14</span><div class=\"vt-t\">Los Asesores <mark class=\"m-accion\">prestarán</mark> al <mark class=\"m-autoridad\">Defensor</mark> del Pueblo y a los Adjuntos: → <mark class=\"m-resp\">la cooperación técnico-jurídica necesaria para el cumplimiento de sus funciones</mark></div></div><div class=\"vt-hoja\"><span class=\"vt-p o\">R15</span><div class=\"vt-t\">El presupuesto de la Institución del <mark class=\"m-autoridad\">Defensor</mark> del Pueblo <mark class=\"m-accion\">se integrará</mark> en: → <mark class=\"m-resp\">la sección presupuestaria del presupuesto de las Cortes Generales como un servicio más del mismo</mark></div></div></div></div></div></div>"},{"t":"Plazos del Reglamento (resumen)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⏱</i>Plazos del Reglamento (resumen)</div><div class=\"vis-plazos\"><div class=\"vis-plazo\"><span class=\"n\">15 días</span>Propuesta de nombramiento de Adjuntos tras la elección (art. 13.2)</div><div class=\"vis-plazo\"><span class=\"n\">10 días</span>Los Adjuntos deben cesar en toda incompatibilidad desde su nombramiento y antes de tomar posesión (art. 15.1)</div><div class=\"vis-plazo\"><span class=\"n\">4 años</span>Vocales del <mark class=\"m-autoridad\">Consejo</mark> Asesor, renovados <mark class=\"m-resp\">por mitades cada dos</mark> (art. 20.1) · candidaturas: <mark class=\"m-resp\">15 días naturales</mark> desde la convocatoria (art. 20.2)</div><div class=\"vis-plazo\"><span class=\"n\">2 veces / año</span>Reuniones mínimas del <mark class=\"m-autoridad\">Consejo</mark> Asesor (art. 21.1) · máximo 10 Vocales (art. 19.2)</div><div class=\"vis-plazo\"><span class=\"n\">2 meses · 6 meses · 1 año</span>Prescripción de las faltas leves · graves · muy graves, y mismos plazos para las sanciones (art. 36.3)</div><div class=\"vis-plazo\"><span class=\"n\">6 meses a 6 años</span>Sanción de las faltas muy graves (art. 37.1.c) · graves: hasta 6 meses · leves: 1 a 10 días</div></div></div>"}],"b-8":[{"t":"Competencias del Defensor del Pueblo (art. 8) · además de las básicas de la Ley Orgánica","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Competencias del Defensor del Pueblo (art. 8) · además de las básicas de la Ley Orgánica</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-autoridad\">Defensor</mark> <mark class=\"m-destacable\">del Pueblo</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">Representación y relaciones<div class=\"vis-sub\"><span><mark class=\"m-resp\">Representar</mark> a la Institución</span><span><mark class=\"m-resp\">Proponer a los Adjuntos</mark> (conformidad previa de la <mark class=\"m-autoridad\">Comisión</mark> Mixta Congreso-Senado para nombramiento y cese)</span><span>Relación directa con las Cortes Generales <mark class=\"m-autoridad\">(Presidente</mark> del Congreso; ambas Cámaras: sus Presidentes)</span><span>Relación directa con el <mark class=\"m-autoridad\">Presidente</mark> y Vicepresidentes del <mark class=\"m-autoridad\">Gobierno, Ministros</mark> y Secretarios de <mark class=\"m-autoridad\">Estado, Delegados del Gobierno</mark> en las CCAA</span><span>Relación directa con el <mark class=\"m-autoridad\">Tribunal</mark> Constitucional y el CGPJ (a través de sus Presidentes) y con el <mark class=\"m-autoridad\">Fiscal</mark> General del <mark class=\"m-autoridad\">Estado</mark></span><span>Relación directa con los Presidentes de los Consejos Ejecutivos de las CCAA y con los <mark class=\"m-autoridad\">órganos</mark> similares al <mark class=\"m-autoridad\">Defensor</mark></span></div></div><div class=\"vis-rama\">Mecanismo Nacional de Prevención y Junta<div class=\"vis-sub\"><span><mark class=\"m-destacable\">Designar</mark> al <mark class=\"m-autoridad\">Presidente del Consejo</mark> Asesor, de entre sus Adjuntos, y a los Vocales</span><span><mark class=\"m-destacable\">Convocar y fijar el orden del día</mark> de la Junta de Coordinación y Régimen Interior y dirigir sus deliberaciones</span></div></div><div class=\"vis-rama\">Personal y presupuesto<div class=\"vis-sub\"><span>Establecer la plantilla y proceder al nombramiento y cese del <mark class=\"m-autoridad\">Secretario</mark> General y del personal</span><span><mark class=\"m-destacable\">Aprobar</mark> el proyecto de presupuesto (de acuerdo con las directrices de las Mesas del Congreso y del Senado) y acordar su remisión al <mark class=\"m-autoridad\">Presidente</mark> del Congreso</span><span><mark class=\"m-destacable\">Fijar</mark> las directrices para la ejecución del presupuesto</span><span><mark class=\"m-resp\">Ejercer la potestad disciplinaria</mark></span><span>Aprobar las bases de selección de personal y de contratación de obras y suministros (arts. 31 y 42)</span><span>Aprobar las instrucciones de orden interno y supervisar el funcionamiento de la Institución</span></div></div></div></div></div>"}],"b-12":[{"t":"Competencias de los Adjuntos (art. 12.1)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Competencias de los Adjuntos (art. 12.1)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">Adjuntos</mark> del <mark class=\"m-autoridad\">Defensor</mark> del Pueblo</div><div class=\"vis-ramas\"><div class=\"vis-rama\"><mark class=\"m-resp\">Ejercitar</mark> las funciones del <mark class=\"m-autoridad\">Defensor</mark> en los casos de <mark class=\"m-resp\">delegación y sustitución</mark> previstos en la Ley Orgánica</div><div class=\"vis-rama\"><mark class=\"m-resp\">Dirigir la tramitación, comprobación e investigación</mark> de las quejas y de las actuaciones de oficio (admisión a trámite o rechazo y resoluciones)</div><div class=\"vis-rama\"><mark class=\"m-destacable\">Colaborar</mark> con el <mark class=\"m-autoridad\">Defensor</mark> en las relaciones con las Cortes Generales y la <mark class=\"m-autoridad\">Comisión</mark> Mixta y en la coordinación con los <mark class=\"m-autoridad\">órganos</mark> similares de las CCAA</div><div class=\"vis-rama\"><mark class=\"m-destacable\">Colaborar</mark> con el <mark class=\"m-autoridad\">Defensor</mark> en el ejercicio de sus funciones como Mecanismo Nacional de Prevención</div><div class=\"vis-rama\"><mark class=\"m-destacable\">Preparar y proponer</mark> el borrador del informe anual y de los demás informes que deban elevarse a las Cortes Generales y al Subcomité para la Prevención de la Tortura</div><div class=\"vis-rama\">Asumir las restantes funciones que se les encomienden en las leyes y disposiciones reglamentarias</div></div></div></div>"}],"b-16":[{"t":"Causas de cese de los Adjuntos (art. 16.1)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Causas de cese de los Adjuntos (art. 16.1)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">Los Adjuntos</mark> <mark class=\"m-accion\">cesarán</mark> por</div><div class=\"vis-ramas\"><div class=\"vis-rama\"><mark class=\"m-resp\">Renuncia</mark></div><div class=\"vis-rama\"><mark class=\"m-resp\">Expiración del plazo</mark> de su nombramiento</div><div class=\"vis-rama\"><mark class=\"m-resp\">Muerte</mark> o <mark class=\"m-resp\">incapacidad sobrevenida</mark></div><div class=\"vis-rama\"><mark class=\"m-resp\">Notoria negligencia</mark> en el cumplimiento de sus obligaciones y deberes (propuesta razonada del <mark class=\"m-autoridad\">Defensor,</mark> aprobada por la <mark class=\"m-autoridad\">Comisión</mark> Mixta Congreso-Senado con el mismo procedimiento y mayoría que para otorgar la conformidad previa, con <mark class=\"m-autoridad\">audiencia</mark> del interesado)</div><div class=\"vis-rama\">Haber sido <mark class=\"m-resp\">condenado</mark>, mediante sentencia firme, por <mark class=\"m-resp\">delito doloso</mark></div><div class=\"vis-rama\">El cese se publica en el <mark class=\"m-destacable\">BOE</mark> y en los diarios de sesiones de ambas Cámaras (art. 16.2)</div></div></div></div>"}],"b-18":[{"t":"Competencias de la Junta de Coordinación y Régimen Interior (art. 18.1)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Competencias de la Junta de Coordinación y Régimen Interior (art. 18.1)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">Junta de Coordinación y Régimen Interior</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\">Informa<div class=\"vis-sub\"><span>Plantilla y nombramiento y cese del personal (a)</span><span>Candidaturas a Vocales del <mark class=\"m-autoridad\">Consejo</mark> Asesor del MNP (i)</span><span>Proyecto de reforma del Reglamento (j)</span><span>Asuntos de elaboración del proyecto de presupuesto, su ejecución y su liquidación, antes de remitirlo a las Cortes (c)</span></div></div><div class=\"vis-rama\">Conoce<div class=\"vis-sub\"><span>Posible interposición de recursos de amparo e inconstitucionalidad (b)</span><span>Proyectos de informes que deban elevarse a las Cortes y al Subcomité (g)</span><span>Nombramiento y cese del <mark class=\"m-autoridad\">Secretario</mark> General (h)</span></div></div><div class=\"vis-rama\">Delibera, asiste y coopera<div class=\"vis-sub\"><span>Propuestas de obras, servicios y suministros (d)</span><span>Asiste al <mark class=\"m-autoridad\">Defensor</mark> en sus competencias de personal y económico-financieras (e)</span><span>Coopera con el <mark class=\"m-autoridad\">Defensor</mark> en la coordinación de las distintas áreas (f)</span><span>Asesora al <mark class=\"m-autoridad\">Defensor</mark> sobre las cuestiones que someta a su consideración (k)</span></div></div><div class=\"vis-rama\">Sesiones (18.2): pueden asistir, debidamente convocados, <mark class=\"m-resp\">los responsables de área</mark> y otras <mark class=\"m-autoridad\">personas</mark> que el <mark class=\"m-autoridad\">Defensor</mark> considere oportunas · el orden del día se comunica a todos los componentes (18.3)</div></div></div></div>"}],"a-23":[{"t":"Competencias del Secretario General (art. 23.1)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Competencias del Secretario General (art. 23.1)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-autoridad\">Secretario</mark> <mark class=\"m-destacable\">General</mark></div><div class=\"vis-ramas\"><div class=\"vis-rama\"><mark class=\"m-resp\">Gobierno y régimen disciplinario</mark> de todo el personal (salvo lo atribuido al <mark class=\"m-autoridad\">Defensor,</mark> los Adjuntos o la Junta)</div><div class=\"vis-rama\"><mark class=\"m-destacable\">Dirigir</mark> los servicios dependientes de la <mark class=\"m-autoridad\">Secretaría</mark> General</div><div class=\"vis-rama\"><mark class=\"m-destacable\">Preparar y presentar</mark> a la Junta las propuestas de selección de los Asesores y demás personal</div><div class=\"vis-rama\"><mark class=\"m-destacable\">Preparar y elevar</mark> a la Junta el <mark class=\"m-resp\">anteproyecto de presupuesto</mark></div><div class=\"vis-rama\"><mark class=\"m-destacable\">Administrar</mark> los créditos para gastos del Presupuesto del <mark class=\"m-autoridad\">Defensor</mark> del Pueblo</div><div class=\"vis-rama\"><mark class=\"m-destacable\">Redactar</mark> las actas y notificar los acuerdos de la Junta</div><div class=\"vis-rama\"><mark class=\"m-destacable\">Convocar</mark>, por indicación del <mark class=\"m-autoridad\">Presidente, el Consejo</mark> Asesor del MNP y levantar acta de sus reuniones</div><div class=\"vis-rama\">En caso de vacante, ausencia o enfermedad: sustituido interinamente por el <mark class=\"m-resp\">Director que designe el Defensor</mark>, oída la Junta (23.2)</div></div></div></div>"}],"a-25":[{"t":"Servicio de Régimen Económico (art. 25)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Servicio de Régimen Económico (art. 25)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-destacable\">Servicio de Régimen Económico</mark>: tres unidades</div><div class=\"vis-ramas\"><div class=\"vis-rama\"><mark class=\"m-resp\">Sección de Asuntos Económicos y Contabilidad</mark></div><div class=\"vis-rama\"><mark class=\"m-resp\">Sección de Habilitación</mark></div><div class=\"vis-rama\"><mark class=\"m-resp\">Sección de Personal y Asuntos Generales</mark></div></div></div></div>"}],"b-19":[{"t":"Composición del Consejo Asesor del MNP (art. 19)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Composición del Consejo Asesor del MNP (art. 19)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\"><mark class=\"m-autoridad\">Consejo</mark> <mark class=\"m-destacable\">Asesor</mark>: <mark class=\"m-autoridad\">órgano</mark> de <mark class=\"m-resp\">cooperación técnica y jurídica</mark> del Mecanismo Nacional de Prevención</div><div class=\"vis-ramas\"><div class=\"vis-rama\"><mark class=\"m-resp\">Los Adjuntos</mark> del <mark class=\"m-autoridad\">Defensor</mark> del Pueblo, como <mark class=\"m-resp\">miembros natos</mark></div><div class=\"vis-rama\">Además, un <mark class=\"m-resp\">máximo de 10 Vocales</mark> (mayores de edad, en pleno disfrute de sus derechos civiles y políticos, con reconocida trayectoria en la defensa de los Derechos Humanos)</div><div class=\"vis-rama\">Designación de los Vocales (19.5)<div class=\"vis-sub\"><span>Un Vocal a propuesta del <mark class=\"m-autoridad\">Consejo</mark> General de la Abogacía de España</span><span>Un Vocal a propuesta de la Organización Médica Colegial</span><span>Un Vocal a propuesta del <mark class=\"m-autoridad\">Consejo</mark> General de Colegios Oficiales de Psicólogos de España</span><span><mark class=\"m-resp\">Hasta dos</mark> Vocales a propuesta conjunta de los organismos con convenios de colaboración con el <mark class=\"m-autoridad\">Defensor</mark> (no más de un representante por entidad)</span><span><mark class=\"m-resp\">Cinco</mark> Vocales elegidos de entre las candidaturas presentadas al <mark class=\"m-autoridad\">Defensor</mark> del Pueblo (a título personal o en representación de la sociedad civil)</span></div></div><div class=\"vis-rama\">El Adjunto en el que el <mark class=\"m-autoridad\">Defensor</mark> delegue las funciones del MNP <mark class=\"m-destacable\">asume la</mark> <mark class=\"m-autoridad\">presidencia</mark> (sustituido por el otro Adjunto en caso de ausencia o vacante) · actúa como <mark class=\"m-autoridad\">secretario el Secretario</mark> <mark class=\"m-destacable\">General</mark></div></div></div></div>"}],"b-20":[{"t":"Plazos del Consejo Asesor (art. 20)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⏱</i>Plazos del Consejo Asesor (art. 20)</div><div class=\"vis-plazos\"><div class=\"vis-plazo\"><span class=\"n\">4 años</span>Mandato de los Vocales, <mark class=\"m-resp\">renovados por mitades cada dos</mark></div><div class=\"vis-plazo\"><span class=\"n\">15 días naturales</span>Para presentar candidaturas desde la publicación de la convocatoria pública</div><div class=\"vis-plazo\"><span class=\"n\">Hasta la designación</span>Los Vocales cesantes continúan ejerciendo sus funciones hasta que se designe a los nuevos</div></div></div>"}],"b-36":[{"t":"Prescripción de las faltas y de las sanciones (art. 36)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⏱</i>Prescripción de las faltas y de las sanciones (art. 36)</div><div class=\"vis-plazos\"><div class=\"vis-plazo\"><span class=\"n\">2 meses</span><mark class=\"m-resp\">Faltas leves</mark></div><div class=\"vis-plazo\"><span class=\"n\">6 meses</span><mark class=\"m-resp\">Faltas graves</mark></div><div class=\"vis-plazo\"><span class=\"n\">1 año</span><mark class=\"m-resp\">Faltas muy graves</mark></div><div class=\"vis-plazo\"><span class=\"n\">Cómputo</span>Las faltas, desde que se cometieron; las sanciones, desde el día en que adquirió firmeza la resolución o se quebrantó su cumplimiento</div></div></div>"}],"b-37":[{"t":"Sanciones por faltas del personal (art. 37.1)","h":"<div class=\"vis\"><div class=\"vis-t\"><i>⏱</i>Sanciones por faltas del personal (art. 37.1)</div><div class=\"vis-plazos\"><div class=\"vis-plazo\"><span class=\"n\">1 a 10 días</span><mark class=\"m-resp\">Falta leve</mark>: apercibimiento o suspensión de empleo y remuneración</div><div class=\"vis-plazo\"><span class=\"n\">Hasta 6 meses</span><mark class=\"m-resp\">Falta grave</mark>: suspensión de empleo y remuneración</div><div class=\"vis-plazo\"><span class=\"n\">6 meses a 6 años</span><mark class=\"m-resp\">Falta muy grave</mark>: suspensión de empleo y remuneración o separación del servicio</div></div></div>"}]};